- В `initState`: `WidgetsBinding.instance.addObserver(this);`
- В `dispose`: `WidgetsBinding.instance.removeObserver(this); _observerDisposed = true;`
- В `didChangeAppLifecycleState`: если состояние == `AppLifecycleState.resumed` и не первый запуск, то `_loadInitialData()`

Теперь давайте реализуем это.

Но ещё нужно подумать о том, что сейчас код использует `.then()`, а не async/await. Давайте приведём к единому стилю.

Также нужно учесть что `CurrencyPageRequest` имеет default `base: 'EUR'`, но по конвенции v2 мы должны использовать `base: 'USD'`. В текущем коде уже используется `'USD'`, это правильно.

Теперь давайте напишем код:

```dart
import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<void> _initFuture;

  List<CurrencyModel> _allCurrencies = [];
  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;
  bool _isFirstLaunch = true;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && !_isFirstLaunch) {
      _loadInitialData();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _initData() async {
    await _loadInitialData();
  }

  Future<void> _loadInitialData() async {
    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _isLoadingMore = true; // используем для блокировки UI
    });

    try {
      final page = await currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20));

      if (!mounted) return;

      _allCurrencies = page.items;
      _filteredCurrenciesNotifier = ValueNotifier(List.from(_allCurrencies));
      _currentPage = 0;
      _hasMore = page.hasMore;
      _isFirstLaunch = false;

      await currencyRepository.saveCurrencyList(_allCurrencies);

      if (mounted) {
        setState(() => _isLoadingMore = false);
        _fadeController.forward();
      }
    } catch (e) {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  Future<void> _loadNextPage() async {
    if (!_hasMore || _isLoadingMore) return;

    final currencyRepository = context.read<CurrencyRepository>();

    setState(() => _isLoadingMore = true);

    try {
      final nextPage = _currentPage + 1;
      final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: nextPage, pageSize: 20));

      if (!mounted) return;

      if (page.items.isNotEmpty) {
        _allCurrencies.addAll(page.items);
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
      }

      _currentPage = nextPage;
      _hasMore = page.hasMore;
    } finally {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<void>(
        future: _initFuture, // Wait for init to complete before showing content
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting && !snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_hasMore && !_isLoadingMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (index == data.length && _hasMore && !_isLoadingMore) {
                            // Показать кнопку "Показать ещё"
                            return Padding(
                              padding: const EdgeInsets.symmetric(vertical: 16.0),
                              child: Center(
                                child: ElevatedButton(
                                  onPressed: _loadNextPage,
                                  child: Text(context.loc.showMore),
                                ),
                              ),
                            );
                          }

                          final CurrencyModel currency = data[index];
                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
```

Подождите, но я вижу проблему: `_initFuture` не инициализирован. Давайте переделаю:

```dart
late Future<void> _initFuture;
```

В `initState`:
```dart
_initFuture = _loadInitialData();
```

Также нужно проверить что в l10n есть строка "showMore". Проверим это.

Ещё один момент: я использую `_isLoadingMore` для блокировки кнопки и показа индикатора загрузки при загрузке первой страницы, но это может быть запутанно. Давайте разделим состояния:
- `_isInitialLoading` — грузится ли первая страница
- `_isLoadingMore` — грузится ли следующая страница

Или можно просто использовать один флаг и показывать разные UI элементы.

Давайте упростим:
- Для первой загрузки используем `FutureBuilder` с индикатором
- Для подгрузки используем отдельный флаг `_isLoadingMore` и кнопку, которая показывает `CircularProgressIndicator` пока грузится

Также, я заметил что в текущем коде используется `_currencyListFuture` для показа данных через `FutureBuilder`. Это работает потому что `FutureBuilder` ждёт завершения Future и потом показывает данные. Но это не совсем правильно — после того как Future завершён, `FutureBuilder` не будет обновляться при изменении данных.

Давайте подумаем о правильном подходе:
1. Первая загрузка: используем `FutureBuilder` или просто загружаем в `initState` и показываем данные когда они готовы
2. Подгрузка: вызываем `_loadNextPage()` по нажатию кнопки и обновляем список

Вариант 1 (без FutureBuilder для данных):
```dart
@override
void initState() {
  super.initState();
  _filteredCurrenciesNotifier = ValueNotifier([]);
  WidgetsBinding.instance.addObserver(this);
  _initAnimation();
  _loadInitialData();
}

Future<void> _loadInitialData() async {
  // ... загружаем данные
  if (mounted) {
    setState(() {}); // обновляем UI после загрузки
  }
}
```

В `build`:
```dart
body: _filteredCurrenciesNotifier.value.isEmpty && !_isLoaded
    ? const Center(child: CircularProgressIndicator())
    : FadeTransition(...)
```

Это проще и понятнее. Давайте так и сделаем.

Но нужно ещё проверить l10n на наличие строки для "Показать ещё". Посмотрим.

Давайте также подумаем о том, как правильно реализовать "потерю фокуса". В Flutter:
- `activate()` — вызывается когда виджет вставляется в дерево (становится видимым)
- `deactivate()` — вызывается когда виджет удаляется из дерева
- `didChangeAppLifecycleState(AppLifecycleState.resumed)` — приложение возвращается на передний план

Если мы хотим обновить данные при возвращении на экран, нужно использовать либо `activate()`, либо слушать `resumed`. `activate()` будет срабатывать каждый раз когда виджет становится видимым (включая начальное появление), а `didChangeAppLifecycleState` — только при возврате приложения из фона.

Для нашего случая лучше использовать комбинацию:
- В `initState`: `_loadInitialData()`, помечаем `_isFirstLaunch = true`
- В `activate()`: если не первый запуск, то `_loadInitialData()`

Это сработает когда пользователь возвращается на экран после навигации.

Давайте реализуем так:

```dart
@override
void activate() {
  super.activate();
  if (!_isFirstLaunch) {
    _loadInitialData();
  } else {
    _isFirstLaunch = false;
  }
}
```

Это более точно отражает "при потере фокуса экрана" — когда экран был потерян (deactivated), а потом снова активирован.

Хорошо, давайте реализуем финальный вариант.

Ещё вопрос: нужно ли сбрасывать `_filteredCurrenciesNotifier` при повторной загрузке? Да, потому что мы загружаем свежие данные и хотим обновить список полностью. Но нужно убедиться что память не течёт — старый ValueNotifier будет GC'нут.

Давайте напишем финальный код.

