{"content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  final List<CurrencyModel> _allCurrencies = [];

  late final AnimationController _fadeController;

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _loadInitialData();
    _filteredCurrenciesNotifier = ValueNotifier<List<CurrencyModel>>([]);
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _refreshData();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _loadInitialData() {
    context.read<CurrencyRepository>().fetchRates(
          const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20),
        ).then(_onPageLoaded);
  }

  void _refreshData() {
    setState(() {
      _allCurrencies.clear();
      _currentPage = 0;
      _hasMore = true;
      _filteredCurrenciesNotifier.value = [];
    });
    _loadInitialData();
  }

  void _onPageLoaded(CurrencyPage page) {
    setState(() => _isLoadingMore = false);
    if (page.items.isNotEmpty) {
      _allCurrencies.addAll(page.items);
      context.read<CurrencyRepository>().saveCurrencyList(_allCurrencies);
    }
    setState(() {
      _currentPage = page.page;
      _hasMore = page.hasMore;
    });
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final List<CurrencyModel> filtered = _allCurrencies.where((currency) {
      return currency.name.toLowerCase().contains(lowerQuery) ||
          currency.symbol.toLowerCase().contains(lowerQuery);
    }).toList(growable: false);
    setState(() => _filteredCurrenciesNotifier.value = filtered);
  }

  void _loadMore() {
    if (_isLoadingMore || !_hasMore) return;
    setState(() => _isLoadingMore = true);
    context.read<CurrencyRepository>().fetchRates(
        CurrencyPageRequest(base: 'USD', page: _currentPage + 1, pageSize: 20))
        .then(_onPageLoaded)
        .catchError((_) {
      setState(() => _isLoadingMore = false);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
            child: SearchView(onChanged: _filterCurrencies),
          ),
          Expanded(
            child: ValueListenableBuilder<List<CurrencyModel>>(
              valueListenable: _filteredCurrenciesNotifier,
              builder: (BuildContext context, List<CurrencyModel> data, _) {
                if (_allCurrencies.isEmpty && !_hasMore) {
                  return const SizedBox.shrink();
                }
                return ListView.builder(
                  itemCount: data.length + (_isLoadingMore ? 1 : 0),
                  itemBuilder: (BuildContext context, int index) {
                    if (_isLoadingMore && index == data.length) {
                      return const Center(
                        child: Padding(
                          padding: EdgeInsets.all(16),
                          child: CircularProgressIndicator(),
                        ),
                      );
                    }
                    final CurrencyModel currency = data[index];
                    return Padding(
                      key: ValueKey(currency.id),
                      padding: index == 0
                          ? const EdgeInsets.only(top: 20)
                          : const EdgeInsets.only(top: 10),
                      child: CurrencyCard(model: currency),
                    );
                  },
                  padding: const EdgeInsets.fromLTRB(22, 0, 22, 80),
                );
              },
            ),
          ),
        ],
      ),
      bottomSheet: !_hasMore || _allCurrencies.isEmpty
          ? const SizedBox.shrink()
          : Container(
              padding: const EdgeInsets.all(16),
              child: ElevatedButton(
                onPressed: _loadMore,
                child: Text(context.loc.showMore),
              ),
            ),
    );
  }
}
