import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('CurrencyListPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();

    final currencyItems = [
      CurrencyModel(
        id: '1',
        nominal: 1,
        name: 'Доллар США',
        symbol: 'USD',
        value: 78.4181,
        previousValue: 78.5,
      ),
      CurrencyModel(
        id: '2',
        nominal: 1,
        name: 'Евро',
        symbol: 'EUR',
        value: 92.7440,
        previousValue: 92.2,
      ),
    ];

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false),
      );
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display all currency items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('USD'), findsOneWidget);
      expect(find.text('EUR'), findsOneWidget);
      expect(find.text('JPY'), findsNothing);
      expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length));
    });

    testWidgets('should navigate to detail page when currency card is tapped', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.tap(find.byType(CurrencyCard).first);
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyDetailPage), findsOneWidget);
    });

    testWidgets('should filter currencies when search text is entered', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.enterText(find.byType(TextField), 'Евро');
      await tester.pump();

      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should hide "Show more" button when hasMore is false', (WidgetTester tester) async {
      // Mock with hasMore: false — no pagination available
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false),
      );

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      // Button text "Показать ещё" (ru) or "Show more" (en) should not appear
      expect(find.text('Показать ещё'), findsNothing);
      expect(find.text('Show more'), findsNothing);
    });

    testWidgets('should show "Show more" button when hasMore is true', (WidgetTester tester) async {
      // Mock with hasMore: true — more pages available
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: true),
      );

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      // Button text should appear
      expect(find.text('Показать ещё'), findsOneWidget);
    });

    testWidgets('should load next page when "Show more" is tapped', (WidgetTester tester) async {
      int callCount = 0;

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((Invocation invocation) {
        if (callCount == 0) {
          // First page
          callCount++;
          return Future.value(CurrencyPage(items: currencyItems, page: 0, hasMore: true));
        } else {
          // Second page
          return Future.value(
            CurrencyPage(
              items: const [
                CurrencyModel(id: '3', nominal: 1, name: 'Йена', symbol: 'JPY', value: 0.67, previousValue: 0.5)
              ],
              page: 1,
              hasMore: false,
            ),
          );
        }
      });

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      // "Show more" button should be visible
      expect(find.text('Показать ещё'), findsOneWidget);

      // Tap the button to load next page
      await tester.tap(find.text('Показать ещё'));
      await tester.pumpAndSettle();

      // JPY from second page should now appear
      expect(find.text('JPY'), findsOneWidget);
    });

    testWidgets('should show loading indicator while fetching more pages', (WidgetTester tester) async {
      final completer = Completer<void>();

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async {
        await completer.future; // Never completes to keep loading state
        return CurrencyPage(items: <CurrencyModel>[], page: 1, hasMore: false);
      });

      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      // First page loads successfully
      await tester.pumpAndSettle();
      expect(find.text('USD'), findsOneWidget);

      // Tap "Show more" to trigger loading state
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async {
        await completer.future;
        return CurrencyPage(items: <CurrencyModel>[], page: 1, hasMore: false);
      });

      await tester.tap(find.text('Показать ещё'));
      await tester.pump(); // Pump once without settling to catch loading indicator

      expect(find.byType(CircularProgressIndicator), findsOneWidget);
    });
  });
}
