      (WidgetTester tester) async {
        int callCount = 0;

        when(mockCurrencyRepository.fetchRates(any)).thenAnswer((Invocation invocation) {
          if (callCount == 0) {
            // First page
            callCount++;
            return Future.value(CurrencyPage(items: currencyItems, page: 0, hasMore: true));
          } else {
            // Second page
            return Future.value(
              CurrencyPage(
                items: const [
                  CurrencyModel(id: '3', nominal: 1, name: 'Йена', symbol: 'JPY', value: 0.67, previousValue: 0.5)
                ],
                page: 1,
                hasMore: false,
              ),
            );
          }
        });

        await tester.pumpWidget(
